=<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>ShelfWise Stock</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Space+Grotesk:wght@500;600&display=swap">
<style>
:root{--bg:#f6f7f9;--panel:#ffffff;--fg:#14171c;--muted:#5f6670;--line:#e3e6ea;--accent:#1f6feb;--ok:#1a7f45;--warn:#b26a00;--bad:#c62828;--soft:#eef2f7;--shadow:0 10px 30px rgba(15,23,42,.12);color-scheme:light}
@media (prefers-color-scheme:dark){:root{--bg:#0e1013;--panel:#171a1f;--fg:#eceef1;--muted:#9aa2ad;--line:#2a2f37;--accent:#5b9dff;--ok:#4cc38a;--warn:#e5a33a;--bad:#f06a6a;--soft:#1f242b;--shadow:0 10px 30px rgba(0,0,0,.5);color-scheme:dark}}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.45 Inter,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
.wrap{max-width:1100px;margin:0 auto;padding:24px max(16px,env(safe-area-inset-right,0px)) 48px max(16px,env(safe-area-inset-left,0px));display:flex;flex-direction:column;gap:20px}
h1,h2{font-family:"Space Grotesk",Inter,system-ui,sans-serif;margin:0}
h1{font-size:1.8rem;font-weight:600;text-wrap:balance}
h2{font-size:1.1rem;font-weight:600}
.top{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:flex-end;gap:12px}
.sub{color:var(--muted);margin:4px 0 0;font-size:.9rem}
.btn{font:inherit;font-weight:600;font-size:.9rem;border-radius:8px;padding:8px 14px;border:1px solid var(--line);background:var(--panel);color:var(--fg);cursor:pointer}
.btn:hover{border-color:var(--muted)}
.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}
.btn.danger{color:var(--bad);border-color:var(--bad);background:transparent}
.btn.small{padding:5px 10px;font-size:.82rem}
.btn:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.btn:disabled{opacity:.5;cursor:default}
.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
@media (max-width:720px){.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
.kpi{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px;min-width:0}
.kpi .l{font-size:.72rem;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:600}
.kpi .v{font-family:"Space Grotesk",Inter,sans-serif;font-size:2.2rem;font-weight:600;line-height:1.15;font-variant-numeric:tabular-nums}
.kpi .n{font-size:.8rem;color:var(--muted)}
.kpi.warn .v{color:var(--warn)}.kpi.bad .v{color:var(--bad)}
.grid2{display:grid;grid-template-columns:minmax(0,3fr) minmax(0,2fr);gap:16px}
@media (max-width:860px){.grid2{grid-template-columns:minmax(0,1fr)}}
.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:12px;min-width:0}
.cardhead{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:10px}
.mini{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums;font-size:.9rem}
.mini th{text-align:left;font-size:.7rem;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:600;padding:6px 8px;border-bottom:1px solid var(--line)}
.mini td{padding:8px;border-bottom:1px solid var(--line)}
.mini tr:last-child td{border-bottom:0}
.mini .r{text-align:right}
.scroll{overflow-x:auto}
.empty{color:var(--muted);text-align:center;padding:18px 8px}
.search{font:inherit;width:260px;max-width:100%;padding:8px 12px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--fg)}
.list{display:flex;flex-direction:column}
.item{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr) minmax(0,1.2fr) auto;gap:12px;align-items:center;padding:10px 4px;border-bottom:1px solid var(--line)}
.item:last-child{border-bottom:0}
.item .name{font-weight:600;overflow-wrap:anywhere}
.item .sup{font-size:.8rem;color:var(--muted);overflow-wrap:anywhere}
.item .qty{font-variant-numeric:tabular-nums}
.item .qty small,.item .exp small{color:var(--muted)}
.act{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}
.btn.sold{color:var(--bad);border-color:var(--bad);background:transparent}
.btn.recv{color:var(--ok);border-color:var(--ok);background:transparent}
.qbig{font:600 1.6rem 'Space Grotesk',Inter,sans-serif;text-align:center;padding:10px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--fg);width:100%}
@media (max-width:640px){.item{grid-template-columns:minmax(0,1fr)}.act{justify-content:flex-start}}
.chip{display:inline-block;font-size:.72rem;font-weight:600;padding:1px 8px;border-radius:999px;border:1px solid currentColor;margin-left:6px;white-space:nowrap}
.chip.ok{color:var(--ok)}.chip.warn{color:var(--warn)}.chip.bad{color:var(--bad)}
.count{font-size:.85rem;color:var(--muted)}
.notice.dup{text-align:left;border-color:var(--warn);color:var(--warn);padding:14px 16px;font-weight:500}
.pager{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;padding-top:6px}
.pager .btn{min-width:38px;padding:6px 10px}
.pager .btn[aria-current="page"]{background:var(--accent);border-color:var(--accent);color:#fff}
.pager .gap{align-self:center;color:var(--muted);padding:0 2px}
.notice{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:24px;text-align:center}
.overlay{position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:flex-end;justify-content:center;padding:16px;z-index:20}
@media (min-width:640px){.overlay{align-items:center}}
.sheet{background:var(--panel);border-radius:14px;box-shadow:var(--shadow);width:100%;max-width:520px;max-height:90vh;overflow:auto;padding:20px;display:flex;flex-direction:column;gap:14px}
.form{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.form .full{grid-column:1/-1}
.field{display:flex;flex-direction:column;gap:4px;min-width:0}
.field label{font-size:.75rem;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}
.field input{font:inherit;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--fg);min-width:0}
.field input[readonly]{opacity:.7}
.adjust{display:flex;gap:8px;flex-wrap:wrap;align-items:center;background:var(--soft);border-radius:10px;padding:10px}
.adjust input{width:100px;font:inherit;padding:6px 10px;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--fg)}
.row{display:flex;gap:8px;flex-wrap:wrap;justify-content:space-between;align-items:center}
.err{color:var(--bad);font-size:.85rem;min-height:1.2em;margin:0}
.toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--fg);color:var(--bg);padding:10px 16px;border-radius:10px;font-weight:600;z-index:30}
.skel{color:transparent!important;background:var(--soft);border-radius:6px}
@media (prefers-reduced-motion:no-preference){.btn{transition:border-color .15s}}
</style>
</head>
<body>
<div class="wrap">
  <div class="top">
    <div>
      <h1 id="shopName">ShelfWise Stock</h1>
      <p class="sub" id="updated">Loading your stock…</p>
    </div>
    <div class="row">
      <button class="btn" id="refreshBtn" type="button">Refresh</button>
      <button class="btn primary" id="addBtn" type="button">+ Add Medicine</button>
    </div>
  </div>

  <div id="denied" class="notice" hidden>
    <h2>This Link Isn't Working</h2>
    <p class="sub" id="deniedMsg">Contact Ishfaq Builds for a new link.</p>
  </div>

  <div id="app" style="display:flex;flex-direction:column;gap:20px">
    <div class="notice dup" id="dupWarn" role="alert" hidden></div>
    <div class="kpis">
      <div class="kpi warn"><div class="l">To Reorder</div><div class="v skel" id="kReorder">0</div><div class="n">At or below min stock</div></div>
      <div class="kpi bad"><div class="l">Out Of Stock</div><div class="v skel" id="kOut">0</div><div class="n">Quantity is 0</div></div>
      <div class="kpi warn"><div class="l">Expiring In 30 Days</div><div class="v skel" id="kExpiring">0</div><div class="n">Sell or return first</div></div>
      <div class="kpi bad"><div class="l">Expired</div><div class="v skel" id="kExpired">0</div><div class="n">Remove from shelf</div></div>
    </div>

    <div class="grid2">
      <div class="card">
        <h2>Order Today</h2>
        <div class="scroll"><table class="mini"><thead><tr><th>Supplier</th><th>Medicine</th><th class="r">Left</th><th class="r">Order</th><th>Phone</th></tr></thead><tbody id="orders"></tbody></table></div>
        <nav class="pager" id="ordersPager" aria-label="Order Today pages"></nav>
      </div>
      <div class="card">
        <h2>Expiring Soon</h2>
        <div class="scroll"><table class="mini"><thead><tr><th>Medicine</th><th>Expiry</th><th class="r">Days</th></tr></thead><tbody id="expiry"></tbody></table></div>
        <nav class="pager" id="expiryPager" aria-label="Expiring Soon pages"></nav>
      </div>
    </div>

    <div class="card">
      <div class="cardhead">
        <div><h2>All Stock</h2><span class="count" id="count"></span></div>
        <input class="search" id="search" type="search" placeholder="Search medicine or supplier" aria-label="Search stock">
      </div>
      <div class="list" id="list"></div>
      <nav class="pager" id="pager" aria-label="Stock pages"></nav>
    </div>
  </div>
</div>

<div class="overlay" id="editor" hidden>
  <div class="sheet" role="dialog" aria-modal="true" aria-labelledby="edTitle">
    <h2 id="edTitle">Edit Medicine</h2>
    <form class="form" id="edForm" novalidate>
      <div class="field full"><label for="fMed">Medicine</label><input id="fMed" maxlength="100" autocomplete="off" required></div>
      <div class="field"><label for="fQty">Quantity</label><input id="fQty" type="number" min="0" step="1" inputmode="numeric" required></div>
      <div class="field"><label for="fMin">Min Stock</label><input id="fMin" type="number" min="0" step="1" inputmode="numeric" required></div>
      <div class="adjust full" id="adjust">
        <input id="fAmt" type="number" min="1" step="1" inputmode="numeric" placeholder="Amount" aria-label="Amount">
        <button class="btn small" type="button" id="soldBtn">− Sold</button>
        <button class="btn small" type="button" id="recvBtn">+ Received</button>
      </div>
      <div class="field"><label for="fReo">Reorder Qty</label><input id="fReo" type="number" min="0" step="1" inputmode="numeric" placeholder="Auto"></div>
      <div class="field"><label for="fExp">Expiry Date</label><input id="fExp" type="date"></div>
      <div class="field"><label for="fSup">Supplier</label><input id="fSup" maxlength="100" autocomplete="off"></div>
      <div class="field"><label for="fPhone">Supplier Phone</label><input id="fPhone" inputmode="tel" maxlength="20" autocomplete="off"></div>
    </form>
    <p class="err" id="edErr" role="alert"></p>
    <div class="row">
      <button class="btn danger" type="button" id="delBtn">Delete</button>
      <div class="row">
        <button class="btn" type="button" id="cancelBtn">Cancel</button>
        <button class="btn primary" type="button" id="saveBtn">Save</button>
      </div>
    </div>
  </div>
</div>

<div class="overlay" id="quick" hidden>
  <div class="sheet" role="dialog" aria-modal="true" aria-labelledby="qTitle">
    <h2 id="qTitle">Sold</h2>
    <p class="sub" id="qInfo"></p>
    <div class="field"><label for="qAmt" id="qLabel">How many?</label><input class="qbig" id="qAmt" type="number" min="1" step="1" inputmode="numeric"></div>
    <p class="err" id="qErr" role="alert"></p>
    <div class="row" style="justify-content:flex-end">
      <button class="btn" type="button" id="qCancel">Cancel</button>
      <button class="btn primary" type="button" id="qOk">Confirm</button>
    </div>
  </div>
</div>

<div class="toast" id="toast" hidden></div>

<script>
const CFG = { key: "{{ String($json.query.key || '').replace(/[^A-Za-z0-9]/g, '') }}", api: "{{ 'https://' + String($json.headers['x-forwarded-host'] || $json.headers.host || '').replace(/[^A-Za-z0-9.:-]/g, '') + '/webhook/' }}" };
const $ = (id) => document.getElementById(id);
let items = [];
let editing = null;
let delArmed = false;
const PAGE_SIZE = 20;
const SMALL_PAGE = 6;
let page = 1, ordersPage = 1, expiryPage = 1;

const num = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const today = () => { const n = new Date(); return Date.UTC(n.getFullYear(), n.getMonth(), n.getDate()); };
const daysTo = (d) => /^\d{4}-\d{2}-\d{2}$/.test(String(d || '')) ? Math.round((Date.parse(d + 'T00:00:00Z') - today()) / 86400000) : null;
const status = (it) => {
  const q = num(it.Quantity) || 0, m = num(it.MinStock) || 0, days = daysTo(it.ExpiryDate);
  return { q, m, days, low: q <= m, out: q === 0, expired: days !== null && days < 0, expiring: days !== null && days >= 0 && days <= 30,
           order: q <= m ? (num(it.ReorderQty) || Math.max(m * 2 - q, 1)) : null };
};
const td = (text, cls) => { const c = document.createElement('td'); if (cls) c.className = cls; c.textContent = text === null || text === undefined || text === '' ? '—' : String(text); return c; };
const emptyRow = (tbody, cols, text) => { const tr = document.createElement('tr'); const c = td(text, 'empty'); c.colSpan = cols; tr.appendChild(c); tbody.replaceChildren(tr); };
const chip = (text, tone) => { const s = document.createElement('span'); s.className = 'chip ' + tone; s.textContent = text; return s; };
const toast = (msg) => { const t = $('toast'); t.textContent = msg; t.hidden = false; clearTimeout(toast._t); toast._t = setTimeout(() => { t.hidden = true; }, 2500); };

const norm = (s) => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]/gu, '');
function renderDupes() {
  const groups = new Map();
  items.forEach((it) => { const k = norm(it.Medicine); groups.set(k, (groups.get(k) || []).concat(it.Medicine)); });
  const dupes = [...groups.values()].filter((g) => g.length > 1).map((g) => g[0]);
  const el = $('dupWarn');
  el.hidden = !dupes.length;
  if (dupes.length) el.textContent = '⚠️ Duplicate medicines in your sheet: ' + dupes.join(', ') + '. Delete the extra rows in Google Sheets so stock stays correct.';
}
function render() {
  renderDupes();
  const s = items.map((it) => ({ it, st: status(it) }));
  [['kReorder', s.filter((x) => x.st.low).length], ['kOut', s.filter((x) => x.st.out).length],
   ['kExpiring', s.filter((x) => x.st.expiring).length], ['kExpired', s.filter((x) => x.st.expired).length]]
    .forEach(([id, v]) => { const el = $(id); el.textContent = v; el.classList.remove('skel'); });

  const orders = s.filter((x) => x.st.low).sort((a, b) => String(a.it.Supplier || '').localeCompare(String(b.it.Supplier || '')) || a.st.q - b.st.q);
  const oPages = Math.max(1, Math.ceil(orders.length / SMALL_PAGE)); if (ordersPage > oPages) ordersPage = oPages;
  makePager('ordersPager', oPages, ordersPage, (n) => { ordersPage = n; render(); });
  const oShown = orders.slice((ordersPage - 1) * SMALL_PAGE, ordersPage * SMALL_PAGE);
  if (!orders.length) emptyRow($('orders'), 5, 'Nothing to reorder.');
  else $('orders').replaceChildren(...oShown.map(({ it, st }) => { const tr = document.createElement('tr'); tr.append(td(it.Supplier), td(it.Medicine), td(st.q, 'r'), td(st.order, 'r'), td(it.SupplierPhone)); return tr; }));

  const exp = s.filter((x) => x.st.expired || x.st.expiring).sort((a, b) => a.st.days - b.st.days);
  const ePages = Math.max(1, Math.ceil(exp.length / SMALL_PAGE)); if (expiryPage > ePages) expiryPage = ePages;
  makePager('expiryPager', ePages, expiryPage, (n) => { expiryPage = n; render(); });
  const eShown = exp.slice((expiryPage - 1) * SMALL_PAGE, expiryPage * SMALL_PAGE);
  if (!exp.length) emptyRow($('expiry'), 3, 'Nothing expiring in 30 days.');
  else $('expiry').replaceChildren(...eShown.map(({ it, st }) => { const tr = document.createElement('tr'); const d = td(st.days < 0 ? 'Expired' : st.days, 'r'); if (st.days < 0) d.style.color = 'var(--bad)'; tr.append(td(it.Medicine), td(it.ExpiryDate), d); return tr; }));

  renderList();
}

function renderList() {
  const q = $('search').value.trim().toLowerCase();
  const list = items.filter((it) => !q || (String(it.Medicine || '') + ' ' + String(it.Supplier || '')).toLowerCase().includes(q))
    .sort((a, b) => String(a.Medicine).localeCompare(String(b.Medicine), undefined, { sensitivity: 'base' }));
  const pages = Math.max(1, Math.ceil(list.length / PAGE_SIZE));
  if (page > pages) page = pages;
  const start = (page - 1) * PAGE_SIZE;
  const shown = list.slice(start, start + PAGE_SIZE);
  $('count').textContent = list.length
    ? (start + 1) + '–' + (start + shown.length) + ' of ' + list.length + (q ? ' found' : ' medicines')
    : (q ? '0 found' : '0 medicines');
  renderPager(pages);
  if (!list.length) {
    const p = document.createElement('p'); p.className = 'empty';
    p.textContent = items.length ? 'No medicines match "' + $('search').value.trim() + '".' : 'No medicines yet. Tap + Add Medicine.';
    $('list').replaceChildren(p); return;
  }
  $('list').replaceChildren(...shown.map((it) => {
    const st = status(it);
    const row = document.createElement('div'); row.className = 'item';
    const a = document.createElement('div');
    const n = document.createElement('div'); n.className = 'name'; n.textContent = it.Medicine;
    const sp = document.createElement('div'); sp.className = 'sup'; sp.textContent = it.Supplier || 'No supplier';
    a.append(n, sp);
    const b = document.createElement('div'); b.className = 'qty';
    b.append(document.createTextNode(String(st.q) + ' '), Object.assign(document.createElement('small'), { textContent: '/ min ' + st.m }));
    if (st.out) b.append(chip('Out', 'bad')); else if (st.low) b.append(chip('Low', 'warn'));
    const c = document.createElement('div'); c.className = 'exp';
    c.append(Object.assign(document.createElement('small'), { textContent: it.ExpiryDate ? 'Exp ' + it.ExpiryDate : 'No expiry' }));
    if (st.expired) c.append(chip('Expired', 'bad')); else if (st.expiring) c.append(chip(st.days + 'd', 'warn'));
    const d = document.createElement('div'); d.className = 'act';
    const mk = (label, cls, aria, fn) => { const b = document.createElement('button'); b.className = 'btn small ' + cls; b.type = 'button'; b.textContent = label; b.setAttribute('aria-label', aria + ' ' + it.Medicine); b.addEventListener('click', fn); return b; };
    d.append(mk('Sold', 'sold', 'Sold', () => openQuick(it, 'sold')), mk('Received', 'recv', 'Received', () => openQuick(it, 'received')), mk('Edit', '', 'Edit', () => openEditor(it)));
    row.append(a, b, c, d);
    return row;
  }));
}

function renderPager(pages) {
  makePager('pager', pages, page, (n) => { page = n; renderList(); $('list').scrollIntoView({ block: 'start', behavior: 'smooth' }); });
}
function makePager(navId, pages, current, go) {
  const nav = $(navId);
  const page = current;
  if (pages <= 1) { nav.replaceChildren(); return; }
  const btn = (label, n, opts) => {
    const b = document.createElement('button'); b.type = 'button'; b.className = 'btn small'; b.textContent = label;
    if (opts && opts.current) b.setAttribute('aria-current', 'page');
    if (opts && opts.aria) b.setAttribute('aria-label', opts.aria);
    if (opts && opts.disabled) b.disabled = true; else b.addEventListener('click', () => go(n));
    return b;
  };
  const nums = new Set([1, pages, page - 1, page, page + 1].filter((n) => n >= 1 && n <= pages));
  const sorted = [...nums].sort((a, b) => a - b);
  const parts = [btn('‹', page - 1, { aria: 'Previous page', disabled: page === 1 })];
  sorted.forEach((n, i) => {
    if (i && n - sorted[i - 1] > 1) { const g = document.createElement('span'); g.className = 'gap'; g.textContent = '…'; parts.push(g); }
    parts.push(btn(String(n), n, { current: n === page, aria: 'Page ' + n }));
  });
  parts.push(btn('›', page + 1, { aria: 'Next page', disabled: page === pages }));
  nav.replaceChildren(...parts);
}

async function load(quiet) {
  if (!CFG.key) return deny('This link has no key. Contact Ishfaq Builds for your link.');
  try {
    const r = await fetch(CFG.api + 'shelfwise-data?key=' + encodeURIComponent(CFG.key), { cache: 'no-store' });
    const data = await r.json();
    if (!data.ok) return deny(data.error);
    items = Array.isArray(data.items) ? data.items : [];
    $('shopName').textContent = data.shop || 'ShelfWise Stock';
    document.title = (data.shop || 'ShelfWise') + ' · Stock';
    $('updated').textContent = 'Updated ' + new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) + ' · Changes also save to your Google Sheet';
    render();
  } catch (e) {
    $('updated').textContent = 'Couldn\'t load stock. Check your internet and tap Refresh.';
    if (!quiet) toast('Couldn\'t load stock');
  }
}
function deny(msg) {
  $('app').style.display = 'none'; $('addBtn').hidden = true; $('refreshBtn').hidden = true;
  $('denied').hidden = false; if (msg) $('deniedMsg').textContent = msg; $('updated').textContent = '';
}

function openEditor(it) {
  editing = it || null; delArmed = false;
  $('edTitle').textContent = it ? 'Edit Medicine' : 'Add Medicine';
  $('fMed').value = it ? it.Medicine : ''; $('fMed').readOnly = !!it;
  $('fQty').value = it ? (num(it.Quantity) ?? 0) : '';
  $('fMin').value = it ? (num(it.MinStock) ?? 0) : '';
  $('fReo').value = it && num(it.ReorderQty) !== null ? it.ReorderQty : '';
